// A simplified implementation of a dynamically injectable store

function configureAppStore(initialState) {
  const store = configureStore({
    reducer: createReducer(), // Start with core reducers
    preloadedState: initialState
  });

  // Add a dictionary to keep track of injected reducers
  store.asyncReducers = {};

  // Add an injection method to the store object
  store.injectReducer = (key, asyncReducer) => {
    store.asyncReducers[key] = asyncReducer;
    // Rebuild the root reducer and replace it
    store.replaceReducer(createReducer(store.asyncReducers));
  };

  return store;
}
